-- Extend only our stock administrator help; preserve operator text/translations.
UPDATE `ai_playerbot_help_texts` SET `template_text`='Administrator commands use normal server permissions, including console and authenticated SOAP.\nrndbot stats reports population; rndbot update requests reconciliation.\nrndbot refresh|upgrade|revive|change_strategy|remove <name-prefix|all> queues bounded work for live random bots.\nrndbot init|teleport|rpg|grind <name-prefix|all> queues eligible random-bot initialization or validated relocation.\nrndbot diff [player-ms empty-ms] reports latency or changes positive activity targets.\nrndbot pid <p> <i> <d> tunes activity; rndbot reset clears persistent events except temporary membership.\nahbot status|reload|rebuild [all]|item <id> manages the selected auction controller.\nperfmon toggle|reset|tick|stack|map controls optional profiling. Unsupported commands report an error.' WHERE `name`='help:admin' AND `template_text`='Administrator commands use normal server permissions, including console and authenticated SOAP.\nrndbot stats reports population; rndbot update requests reconciliation.\nrndbot refresh|upgrade|revive|change_strategy|remove <name-prefix|all> queues bounded work for live random bots.\nrndbot init|teleport|rpg|grind <name-prefix|all> queues eligible random-bot initialization or validated relocation.\nrndbot pid <p> <i> <d> tunes activity; rndbot reset clears persistent events except temporary membership.\nahbot status|reload|rebuild [all]|item <id> manages the selected auction controller.\nperfmon toggle|reset|tick|stack|map controls optional profiling. Unsupported commands report an error.';
